import math

def accept(delta_energy, log_q_reverse_minus_forward, uniform01):
    log_alpha = -delta_energy + log_q_reverse_minus_forward
    return uniform01 == 0 or math.log(uniform01) < min(0.0, log_alpha)

use std::collections::HashMap;
struct Registry { values: Vec<String>, by_name: HashMap<String, usize> }
impl Registry {
 fn insert(&mut self, name: String) -> Result<usize, &'static str> {
  if self.by_name.contains_key(&name) { return Err("duplicate"); }
  let id = self.values.len();
  self.values.push(name.clone());
  self.by_name.insert(name, id);
  Ok(id)
 }
}

